Q: Why doesn&#39;t the string returned by my formatToString() instance method not adhere to the respective test case on freeCodeCamp? A: <p>Your code is “almost” correct; you've just omitted a few <strong>this</strong> references in the <strong>pin()</strong>, <strong>unpin()</strong>, and <strong>count()</strong> methods, and yes, you still need to complete <strong>formatToString()</strong>.<br />
The data needed to complete it, is in the objects <em>ProjectIdea</em>, contained in <strong>ideas</strong>.</p>
<pre><code>
  // ok
const projectStatus = {
  PENDING: {description: &quot;Pending Execution&quot;},
  SUCCESS: {description: &quot;Executed Successfully&quot;},
  FAILURE: {description: &quot;Execution Failed&quot;}
};

  // ok
class ProjectIdea {
  status = projectStatus.PENDING;

  constructor( title, desc ) {
    this.description = desc;
    this.title = title;
  }

  updateProjectStatus( newStatus ) {
    this.status = newStatus;
  }
}

class ProjectIdeaBoard {

  constructor( title ) {
    this.title = title;
    this.ideas = [];
  }

  pin( project ) {

      // add &quot;this&quot;
    this.ideas.push( project );
  }

  unpin( project ) {

      // add &quot;this&quot; an modify so that it deletes the received
      // object and not the last one in the list (although
      // without the fix, it passes the check!!..??)
    this.ideas.splice( this.ideas.indexOf( project ), 1 ); 
  }

  count() {

      // add &quot;this&quot;
    return this.ideas.length;
  }

  formatToString() {    

      // we create the header
    let toReturn = `${this.title} has ${this.ideas.length} idea(s)\n`; 

      // we iterate over **ideas**, passing the
      // data from each object to **toReturn**
    for( let i = 0; i &lt; this.ideas.length; i ++ ) {
      toReturn += `${this.ideas[ i ].title} (${this.ideas[ i ].status.description}) - ${this.ideas[ i ].description}\n`;
    }
    return toReturn;
  }
}
</code></pre>
